canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)*canvas.width/r.width,y=(e.clientY-r.top)*canvas.height/r.height;if(droneCommand){drone.tx=x;drone.ty=y;droneCommand=false;burst(x,y,'#ffffff',8);beep(640,.08);renderUI();return;}let nearest=-1,distance=Math.max(46,Math.min(92,28*canvas.width/r.width));PADS.forEach((p,i)=>{const d=Math.hypot(p[0]-x,p[1]-y);if(d<distance){nearest=i;distance=d;}});if(nearest>=0)selectPad(nearest);else if(!ended){selectedPad=-1;renderUI();}});
function ensureAdvancedUI(){if(!document.querySelector)return;const waveBox=document.querySelector('.wave-info');waveBox.insertAdjacentHTML('beforebegin','<section class="intel-box"><span class="eyebrow">INTELIGÊNCIA DA ONDA</span><strong id="intel"></strong><div class="enemy-legend"><span>◆ rápido</span><span>⬡ escudo</span><span>⬢ blindado</span></div></section><section class="abilities"><button id="drone" aria-label="Reposicionar sentinela">SENTINELA <span>nível 1</span></button><button id="emp" aria-label="Usar pulso eletromagnético">EMP <span>pronto</span></button><button id="surge" aria-label="Ativar sobrecarga das torres">SOBRECARGA <span>pronta</span></button></section>');$('drone').onclick=commandDrone;$('emp').onclick=useEmp;$('surge').onclick=useSurge;const arsenal=document.querySelector('.panel-title span');if(arsenal)arsenal.textContent='01 — 04';const help=document.querySelectorAll('#guide p');if(help[2])help[2].innerHTML='<b>Pulso:</b> tiro crítico. <b>Canhão:</b> explosão, com bônus contra alvos resfriados. <b>Cryo:</b> controle de velocidade. <b>Arco:</b> corrente elétrica entre inimigos. Reposicione a Sentinela e use EMP ou Sobrecarga no momento certo.';const keys=document.querySelector('footer span:last-child');if(keys)keys.innerHTML='ESPAÇO pausa <i>·</i> 1–4 torres <i>·</i> D sentinela <i>·</i> E EMP <i>·</i> S sobrecarga';}
ensureAdvancedUI();
function togglePause(){if(!active||ended)return;paused=!paused;renderUI();}
$('start').onclick=startWave;$('pause').onclick=togglePause;$('speed').onclick=()=>{speed=speed===1?2:1;$('speed').textContent=speed+'× velocidade';};$('again').onclick=reset;
$('reset').onclick=()=>{if(wave===0&&towers.length===0)return;const wasPaused=paused;paused=true;if(confirm('Reiniciar a partida? A defesa atual será perdida.'))reset();else{paused=wasPaused;renderUI();}};
$('sound').onclick=()=>{sound=!sound;$('sound').textContent='Som: '+(sound?'on':'off');$('sound').setAttribute('aria-label',sound?'Desativar som':'Ativar som');beep(600,.12);};
let helpPaused=false;$('help').onclick=()=>{helpPaused=paused;if(active){paused=true;renderUI();}$('guide').showModal();};$('closeHelp').onclick=$('understood').onclick=()=>$('guide').close();$('guide').addEventListener('close',()=>{paused=helpPaused;renderUI();});
document.addEventListener('keydown',e=>{if($('guide').open)return;if(e.key==='Escape'){selectedType=null;selectedPad=-1;droneCommand=false;renderUI();}if(e.target.tagName==='BUTTON')return;if(['1','2','3','4'].includes(e.key))choose(Number(e.key)-1);if(e.key.toLowerCase()==='d')commandDrone();if(e.key.toLowerCase()==='e')useEmp();if(e.key.toLowerCase()==='s')useSurge();if(e.code==='Space'){e.preventDefault();togglePause();}});
