let uiClock=0;function frame(ts){const dt=Math.min((ts-last)/1000,.05);last=ts;update(dt*speed);uiClock+=dt;if(uiClock>.2){uiClock=0;$('gold').textContent=gold;$('lives').innerHTML=lives+' <small>/ 20</small>';$('score').textContent=score.toLocaleString('pt-BR');if(active)$('count').textContent=(pending+enemies.length)+' restantes';updateAbilityUI();const t=towers.find(t=>t.pad===selectedPad);if(t&&$('upgrade'))$('upgrade').disabled=ended||t.level>=3||gold<upgradeCost(t);}draw();requestAnimationFrame(frame);}reset();requestAnimationFrame(frame);
